/**
 * Renders rich-text HTML generated by the TipTap editor in the admin
 * panel (headings, paragraphs, inline images, links, lists).
 *
 * dangerouslySetInnerHTML is necessary here -- there's no other way to
 * display rich text saved this way. This is safe ONLY because content is
 * exclusively written by the single trusted admin user, never by public
 * input. If this project ever adds guest authors, public submissions, or
 * comments, this component must switch to a sanitizer (e.g. DOMPurify)
 * before rendering, or move to a safe rich-text renderer instead of raw
 * HTML injection.
 */
export default function PostContent({ html }: { html: string }) {
  return (
    <div
      className="
        prose prose-invert max-w-none mt-10
        prose-headings:font-heading prose-headings:text-white prose-headings:font-bold
        prose-h2:text-2xl prose-h2:mt-12 prose-h2:mb-4
        prose-h3:text-xl prose-h3:mt-8 prose-h3:mb-3
        prose-p:text-slate-300 prose-p:text-[17px] prose-p:leading-[1.85] prose-p:mb-6
        prose-a:text-[#00B4D8] prose-a:font-medium prose-a:no-underline hover:prose-a:underline
        prose-img:rounded-xl prose-img:my-8 prose-img:shadow-2xl
        prose-strong:text-white prose-strong:font-semibold
        prose-blockquote:border-l-[3px] prose-blockquote:border-l-[#00B4D8]
        prose-blockquote:bg-gradient-to-r prose-blockquote:from-[#00B4D8]/10 prose-blockquote:to-transparent
        prose-blockquote:rounded-r-xl prose-blockquote:py-4 prose-blockquote:px-6 prose-blockquote:not-italic
        prose-blockquote:text-xl prose-blockquote:font-heading prose-blockquote:font-medium
        prose-blockquote:text-white prose-blockquote:my-10
        prose-li:text-slate-300 prose-li:text-[17px] prose-li:leading-[1.85]
        prose-ul:my-6 prose-ol:my-6
        prose-hr:border-t-0 prose-hr:my-14 prose-hr:relative
        first-letter:text-5xl first-letter:font-heading first-letter:font-black
        first-letter:text-[#00B4D8] first-letter:mr-2 first-letter:float-left
        first-letter:leading-[0.85] first-letter:mt-1
      "
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}